import { readFile, writeFile } from "node:fs/promises";

const engineSource = stripExports(await readFile(new URL("./engine.js", import.meta.url), "utf8"));
const aiSource = stripExports((await readFile(new URL("./ai.js", import.meta.url), "utf8")).replace(/^import[^\n]+\n/, ""));
const runnerSource = stripExports(await readFile(new URL("./custom-ai-runner.js", import.meta.url), "utf8"));
const appSource = (await readFile(new URL("./app.js", import.meta.url), "utf8")).replace(/^(?:import[^\n]+\n)+/, "");
const strongAiSource = await readFile(new URL("./strong-ai.js", import.meta.url), "utf8");

const bundle = `/* Generated by build-browser-bundle.mjs. Do not edit directly. */
globalThis.VectorRacingStrongAICode = ${JSON.stringify(strongAiSource)};
(function () {
${engineSource}
globalThis.RacingEngine = { RULES_VERSION, TICKS_PER_SECOND, FIXED_DT, MAX_TICKS, LAPS_TO_WIN, TRACK_HALF_WIDTH, LOOKAHEAD_DISTANCES, initialState, cloneState, legalActions, applyActions, outcome, publicState, actionText, progressRatio, stateKey, trackGeometry, sampleTrack, formatTime };
})();

(function () {
const { legalActions, publicState } = globalThis.RacingEngine;
${aiSource}
globalThis.RacingAI = { AI_LEVELS, chooseAction };
})();

(function () {
${runnerSource}
globalThis.RacingCustomAI = { CUSTOM_AI_LIMITS, validateCustomCode, findLegalAction, CustomAISession };
})();

(function () {
const engine = globalThis.RacingEngine;
const ai = globalThis.RacingAI;
const { CustomAISession, validateCustomCode } = globalThis.RacingCustomAI;
${appSource}
})();
`;

await writeFile(new URL("./browser-bundle.js", import.meta.url), bundle, "utf8");

function stripExports(source) {
  return source.replace(/\bexport\s+/g, "");
}
